    tileJson = raw.fields & MLN_STYLE_SOURCE_INFO_TILE_JSON
      .rawValue != 0 ? try StyleSourceTileInfo(raw: raw.tile_json) : nil
    bounds = raw.fields & MLN_STYLE_SOURCE_INFO_BOUNDS
